package com.autumnharvestc.server.collaboration.artifacts;

import com.autumnharvestc.server.auth.AuthFilter;
import com.autumnharvestc.server.store.UserAccount;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import jakarta.servlet.http.HttpServletRequest;

@RestController
@RequestMapping("/api/v1/workspaces/{ws}/projects/{project}/collaboration")
public class ArtifactController {
    private final ArtifactService artifacts;
    private final RemainingArtifacts remaining;private final com.fasterxml.jackson.databind.ObjectMapper json;
    private final CollaborationTime time;
    private final com.autumnharvestc.server.collaboration.mock.MockLimiter mockLimits;
    public ArtifactController(ArtifactService artifacts,RemainingArtifacts remaining,com.fasterxml.jackson.databind.ObjectMapper json,CollaborationTime time,com.autumnharvestc.server.collaboration.mock.MockLimiter mockLimits){this.artifacts=artifacts;this.remaining=remaining;this.json=json;this.time=time;this.mockLimits=mockLimits;}
    @PostMapping("/previews") public ResponseEntity<?> preview(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,HttpServletRequest request)throws java.io.IOException{var started=time.now();var input=remaining.readRequest(actor,ws,project,request.getInputStream(),started);var body=input.body();return ResponseEntity.status(HttpStatus.CREATED).body(remaining.accepts(body)?remaining.preview(actor,ws,project,body,input.deadline()):artifacts.preview(actor,ws,project,body,input.deadline()));}
    @GetMapping("/previews/{id}") public Object preview(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id){return remaining.preview(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),com.autumnharvestc.server.core.EntityIds.parse(id));}
    @DeleteMapping("/previews/{id}") public ResponseEntity<Void> cancel(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id){artifacts.cancel(actor,ws,project,id);return ResponseEntity.noContent().build();}
    @PostMapping("/publications") public ResponseEntity<?> confirm(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@RequestBody JsonNode body){if(remaining.acceptsConfirmation(com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),body)){var result=remaining.confirm(actor,ws,project,body);return ResponseEntity.status(result.replay()?HttpStatus.OK:HttpStatus.CREATED).body(result.publication());}var result=artifacts.confirm(actor,ws,project,body);return ResponseEntity.status(result.replay()?HttpStatus.OK:HttpStatus.CREATED).body(result.publication());}
    @GetMapping("/publications/{id}") public Object publication(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id){return activity(remaining.publication(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),com.autumnharvestc.server.core.EntityIds.parse(id)));}
    @GetMapping("/publications") public RemainingViews.PublicationPage list(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@RequestParam java.util.Map<String,String> query){return remaining.publications(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),query);}
    @PatchMapping("/publications/{id}") public RemainingViews.Publication patch(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id,@RequestBody JsonNode body){return remaining.patch(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),com.autumnharvestc.server.core.EntityIds.parse(id),body);}
    @PostMapping("/publications/{id}/enable") public Object enable(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id,@RequestBody JsonNode body){return transition(actor,ws,project,id,body,true);}
    @PostMapping("/publications/{id}/disable") public Object disable(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id,@RequestBody JsonNode body){return transition(actor,ws,project,id,body,false);}
    private Object transition(UserAccount actor,String ws,String project,String id,JsonNode body,boolean enabled){var command=body.deepCopy();if(command instanceof com.fasterxml.jackson.databind.node.ObjectNode object)object.put("enabled",enabled);return activity(remaining.patch(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),com.autumnharvestc.server.core.EntityIds.parse(id),command));}
    private Object activity(RemainingViews.Publication publication){if(!(publication instanceof RemainingViews.MockPublication mock))return publication;com.fasterxml.jackson.databind.node.ObjectNode result=json.valueToTree(publication);int active=mockLimits.active(Long.parseLong(mock.id()));String state=mock.enabled()?(active>0?"active":"enabled"):(active>0?"draining":"disabled");result.putObject("activity").put("activeRequests",active).put("state",state).put("stateLabel",switch(state){case "active"->"正在处理请求";case "enabled"->"已启用，运行服务就绪状态按调用检查";case "draining"->"已停用，正在收束已准入请求";default->"已停用，无在途请求";});return result;}
    @DeleteMapping("/publications/{id}") public ResponseEntity<Void> delete(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id,@RequestBody JsonNode body){remaining.delete(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),com.autumnharvestc.server.core.EntityIds.parse(id),body);return ResponseEntity.noContent().build();}
    @GetMapping("/history") public RemainingViews.HistoryPage history(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@RequestParam java.util.Map<String,String> query){return remaining.history(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),query);}
    @GetMapping("/history/{id}") public RemainingViews.HistoryBody historyBody(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id,@RequestParam(required=false)String source){return remaining.historyBody(actor,ws,project,com.autumnharvestc.server.core.EntityIds.parse(id),source);}
    @DeleteMapping("/history/{id}") public ResponseEntity<Void> deleteHistory(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String id,@RequestParam(required=false)String source){remaining.deleteHistory(actor,com.autumnharvestc.server.core.EntityIds.parse(ws),com.autumnharvestc.server.core.EntityIds.parse(project),com.autumnharvestc.server.core.EntityIds.parse(id),source);return ResponseEntity.noContent().build();}
    @GetMapping("/operations/{intentId}") public ArtifactViews.Operation operation(@RequestAttribute(AuthFilter.ATTR_USER)UserAccount actor,@PathVariable String ws,@PathVariable String project,@PathVariable String intentId){return artifacts.operation(actor,ws,project,intentId);}
}
